//! Discover Commands Generated Command and Response.

use zb_core::Direction;

use crate::macros::zcl_command;
use crate::storage::CommandIds;

zcl_command! {
    /// Discover Commands Generated Command.
    Command {
        Global;
        command_id: 0x13;
        direction: Direction::ClientToServer;
        response: Response;
        => crate::global::DiscoverCommandsGenerated;
        fields {
            start_command_id: u8,
            maximum_command_ids: u8,
        }
    }
}

zcl_command! {
    /// Discover commands generated by a remote client cluster.
    ClientCommand {
        Global;
        command_id: 0x13;
        direction: Direction::ServerToClient;
        response: ClientResponse;
        => crate::global::DiscoverClientCommandsGenerated;
        fields {
            start_command_id: u8,
            maximum_command_ids: u8,
        }
    }
}

zcl_command! {
    /// Discover Commands Generated response from a remote client cluster.
    ClientResponse {
        Global;
        command_id: 0x14;
        direction: Direction::ClientToServer;
        => crate::global::DiscoverClientCommandsGeneratedResponse;
        fields {
            discovery_complete: u8,
            command_ids: CommandIds,
        }

        getters {
            /// Return the raw discovery-complete flag.
            #[must_use]
            pub const fn discovery_complete(&self) -> u8 {
                self.discovery_complete
            }

            /// Return the discovered command identifiers.
            #[must_use]
            pub fn command_ids(&self) -> &[u8] {
                &self.command_ids
            }
        }
    }
}

zcl_command! {
    /// Discover Commands Generated Response Command.
    Response {
        Global;
        command_id: 0x14;
        direction: Direction::ServerToClient;
        => crate::global::DiscoverCommandsGeneratedResponse;
        fields {
            discovery_complete: u8,
            command_ids: CommandIds,
        }

        getters {
            /// Return whether command discovery is complete.
            #[must_use]
            pub const fn discovery_complete(&self) -> u8 {
                self.discovery_complete
            }

            /// Return the discovered command identifiers.
            #[must_use]
            pub fn command_ids(&self) -> &[u8] {
                &self.command_ids
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use alloc::vec::Vec;

    use le_stream::ToLeStream;

    use super::{ClientCommand, ClientResponse, Command, Response};
    use crate::{Cluster, Frame, UnsequencedFrame};

    const CLUSTER_ID: u16 = 0x0006;
    const SEQUENCE: u8 = 0x42;
    const START: u8 = 0x01;
    const MAX_IDENTIFIERS: u8 = 0x02;
    const COMPLETE: u8 = 0x01;
    const COMMAND_IDS: [u8; 1] = [0x04];
    const CLIENT_REQUEST: [u8; 5] = [0x08, SEQUENCE, 0x13, START, MAX_IDENTIFIERS];
    const SERVER_REQUEST: [u8; 5] = [0x00, SEQUENCE, 0x13, START, MAX_IDENTIFIERS];
    const CLIENT_RESPONSE: [u8; 5] = [0x10, SEQUENCE, 0x14, COMPLETE, 0x04];
    const SERVER_RESPONSE: [u8; 5] = [0x18, SEQUENCE, 0x14, COMPLETE, 0x04];

    #[test]
    fn serializes_requests_in_each_direction() {
        let client = UnsequencedFrame::try_from_command(ClientCommand::new(START, MAX_IDENTIFIERS))
            .unwrap()
            .with_disable_default_response(false)
            .into_frame(SEQUENCE);
        let server = UnsequencedFrame::try_from_command(Command::new(START, MAX_IDENTIFIERS))
            .unwrap()
            .with_disable_default_response(false)
            .into_frame(SEQUENCE);
        assert_eq!(client.to_le_stream().collect::<Vec<_>>(), CLIENT_REQUEST);
        assert_eq!(server.to_le_stream().collect::<Vec<_>>(), SERVER_REQUEST);
    }

    #[test]
    fn dispatches_discovery_commands_by_direction() {
        let client_request = parse(CLIENT_REQUEST);
        let server_request = parse(SERVER_REQUEST);
        assert!(ClientCommand::try_from(client_request.clone()).is_ok());
        assert!(Command::try_from(client_request).is_err());
        assert!(Command::try_from(server_request.clone()).is_ok());
        assert!(ClientCommand::try_from(server_request).is_err());

        let client_response = parse(CLIENT_RESPONSE);
        let server_response = parse(SERVER_RESPONSE);
        let client = ClientResponse::try_from(client_response.clone()).unwrap();
        let server = Response::try_from(server_response.clone()).unwrap();
        assert_eq!(client.discovery_complete(), COMPLETE);
        assert_eq!(client.command_ids(), COMMAND_IDS);
        assert_eq!(server.command_ids(), COMMAND_IDS);
        assert!(Response::try_from(client_response).is_err());
        assert!(ClientResponse::try_from(server_response).is_err());
    }

    fn parse<const N: usize>(wire: [u8; N]) -> Cluster {
        Frame::parse(CLUSTER_ID, wire.into_iter())
            .unwrap()
            .into_payload()
    }
}
